    if(transportTicks==9210){put("nativeInputAlignmentApply",inputAlignment==InputAlignmentSettings{3,17.25}&&(int64)transportResults["alignmentStartRevision"]==(int64)revision&&!recording&&!recorder.isActive());inputAlignment={};restoreInputSettings();put("nativeInputAlignmentReload",inputAlignment==InputAlignmentSettings{3,17.25});auto state=inputAlignmentState();put("nativeInputAlignmentReport",(bool)state["canResolve"]&&state["resolvedSamples"].isInt64()&&(int64)state["resolvedSamples"]>=0&&!engine->playing.load());}
